define(["marionette", "jquery"], function (Marionette, $) {
    var CandidateManager = new Marionette.Application();

    CandidateManager.addRegions({
        headerRegion: "#header-wrapper",
        bodyRegion: "#app-wrapper",
        footerRegion: "#footer-wrapper"
    });

    CandidateManager.navigate = function (route, options) {
        options || (options = {});
        Backbone.history.navigate(route, options);
    };

    CandidateManager.getCurrentRoute = function () {
        return Backbone.history.fragment
    };

    CandidateManager.startSubApp = function (appName, args) {
        var currentApp = appName ? CandidateManager.module(appName) : null;
        if (CandidateManager.currentApp === currentApp) {
            return;
        }

        if (CandidateManager.currentApp) {
            CandidateManager.currentApp.stop();
        }

        CandidateManager.currentApp = currentApp;
        if (currentApp) {
            currentApp.start(args);
        }

        require(["bootstrap", "metronic", "layoutjs"], function () {
            Metronic.init();
            Layout.init();
        });

        $('body').addClass("candidate_description");
        $('body').addClass("page-md");
        $('body').addClass("overlay");
    };

    CandidateManager.on("start", function () {
        if (Backbone.history) {
            require(["candidates_app"], function () {
                Backbone.history.start();
                if (CandidateManager.getCurrentRoute() === "" && $('#redirectHash').val().indexOf('list') != -1) {
                    CandidateManager.trigger("joblist:show",$('#token').val(), $('#source').val());
                } else if (CandidateManager.getCurrentRoute() === "" && $('#redirectHash').val().indexOf('apply') != -1) {
                    CandidateManager.trigger("jobapplication:show", $('#token').val(), $('#redirectHash').val().split('/')[2], $('#source').val());
                } else if (CandidateManager.getCurrentRoute() === "") {
                    CandidateManager.trigger("jobdescription:show", $('#token').val(), $('#source').val());
                } else if (CandidateManager.getCurrentRoute() === "uploadcandidates") {
                    CandidateManager.trigger("uploadcandidates:list");
                } else if (CandidateManager.getCurrentRoute() === "showcandidates") {
                    CandidateManager.trigger("showcandidates:list");
                } else if (CandidateManager.getCurrentRoute() === "list" ) {
                    CandidateManager.trigger("joblist:show",$('#token').val(), $('#source').val());
                } else if ($('#redirectHash').val().indexOf('messages') != -1) {
                    CandidateManager.trigger("candidateconvmessages:show", $('#redirectHash').val().split('/')[$('#redirectHash').val().split('/').length - 1]);
                }  else if ($('#redirectHash').val().indexOf('thankyou') != -1) {
                    CandidateManager.trigger("candidateconv:show", $('#redirectHash').val().split('/')[$('#redirectHash').val().split('/').length - 1]);
                }else if ($('#redirectHash').val().indexOf('updatedetails') != -1) {
                    CandidateManager.trigger("editCandidateApply:show",$('#token').val(), $('#source').val(), $('#redirectHash').val().split('/')[2], $('#redirectHash').val().split('/')[4],$('#redirectHash').val().split('/')[3]);
                } else if($('#redirectHash').val().indexOf('detail') != -1){
                    if($('#redirectHash').val().indexOf('job') != -1){
                        var  commid= $('#redirectHash').val().split('/')[3];
                        if(commid == 'commid'){
                            CandidateManager.trigger("jobdescriptionforjob:show", $('#token').val(),$('#source').val(), $('#redirectHash').val().split('/')[2],$('#redirectHash').val().split('/')[4]);
                        }else{
                            CandidateManager.trigger("jobdescriptionforjob:show", $('#token').val(),$('#source').val(), $('#redirectHash').val().split('/')[$('#redirectHash').val().split('/').length - 1]);
                        }
                    } else {
                        CandidateManager.trigger("jobdescription:show", $('#token').val(),$('#source').val());
                    }
                } else if($('#redirectHash').val().indexOf('apply') != -1 && $('#redirectHash').val().indexOf('job') != -1){
                    CandidateManager.trigger("jobapplication:show", $('#token').val(),$('#redirectHash').val().split('/')[2],$('#source').val(),$('#redirectHash').val().split('/')[4]);
                } else if($('#redirectHash').val().indexOf('list') != -1){
                    CandidateManager.trigger("joblistnew:show",$('#token').val(), $('#source').val(), $('#redirectHash').val().split('/')[1]);
                }
            });
        }
    });

    /* store defaultConfig */
    CandidateManager.defaultConfig = {};

    /* default setTemplate */
    CandidateManager.setTemplate = function (view) {
        var dfd = $.Deferred();
        var config = CandidateManager.defaultConfig.get("config")[view.getOption("templateConfig")];
        var tplFilePath;
        if (typeof config === "string" && config !== "default") {
            tplFilePath = "tpl!" + view.getOption("templatePath") + "/" + config + "/" + view.getOption("templateName");

        } else {
            tplFilePath = "tpl!" + view.getOption("templatePath") + "/" + view.getOption("templateName");
        }
        require([tplFilePath], function (t) {
            view.template = t;
            dfd.resolve();
        });
        return dfd.promise();
    };

    return CandidateManager;
});

define(["app", "slimscroll"],
    function (CandidateManager) {
        CandidateManager.module("CandidatesApp.Filter.View", function (View, CandidateManager, Backbone, Marionette, $, _) {
            View.FilterPanel = Marionette.ItemView.extend({
                options: {
                    templateConfig: "filter_region",
                    templateName: "filterpanel.tpl",
                    templatePath: "apps/candidates/template/jobdashboard"
                },
                setTemplate: function () {
                    return CandidateManager.setTemplate(this);
                },
                events: {
                    "click .js-filter-remove": "removefilter",
                    "click .js-exp-remove": "removeexpfilter",
                    "click #resetFilters": "clearfilters",
                    "click .js-keyword-remove": "clearkeywordfilter",
                    "click .js-deptfilter-remove": "removedeptfilter",
                    "click .js-bufilter-remove": "removebufilter",
                    "click .js-statefilter-remove": "removestatefilter",
                    "click .js-businessunitfilter-remove": "removebusinessunitfilter",
                    "click .js-accountfilter-remove": "removeaccfilter",
                    "click .js-jobfnfilter-remove": "removejobfnfilter",
                    "click .js-ctp-apply": 'applyForCtp'
                },
                removefilter: function (event) {
                    event.preventDefault();
                    var thisEle = event.currentTarget;
                    this.trigger("removelocation", $(thisEle).attr('data-location'));
                },
                removeexpfilter: function (event) {
                    event.preventDefault();
                    this.trigger("removeexp");
                },
                clearfilters: function (event) {
                    event.preventDefault();
                    this.trigger("clearfilters");
                },
                clearkeywordfilter: function (event) {
                    event.preventDefault();
                    this.trigger("removekeyword");
                },
                removedeptfilter: function (event) {
                    event.preventDefault();
                    var thisEle = event.currentTarget;
                    this.trigger("removedept", $(thisEle).attr('data-department'));
                },
                removebufilter: function (event) {
                    event.preventDefault();
                    var thisEle = event.currentTarget;
                    this.trigger("removebu", $(thisEle).attr('data-bu'));
                },
                removebusinessunitfilter: function (event) {
                    event.preventDefault();
                    var thisEle = event.currentTarget;
                    this.trigger("removebusinessunit", $(thisEle).attr('data-businessunit'));
                },
                removestatefilter: function (event) {
                    event.preventDefault();
                    var thisEle = event.currentTarget;
                    this.trigger("removestate", $(thisEle).attr('data-state'));
                },
                removeaccfilter: function (event) {
                    event.preventDefault();
                    var thisEle = event.currentTarget;
                    this.trigger("removeacc",$(thisEle).attr('data-account'));
                },
                removejobfnfilter: function(event) {
                    event.preventDefault();
                    var thisEle = event.currentTarget;
                    this.trigger("removejobfn",$(thisEle).attr('data-account'));
                },
                applyForCtp : function(event){
                    event.preventDefault();
                    var name = getRefValue()+ " " + getHashValue() + " " + "Ctp";
                    ga('send','event',name) ;
                    this.trigger('jobapplyctp');
                }
            });
        });
        return CandidateManager.CandidatesApp.Filter.View;
    });

define(["app",
        "tpl!apps/candidates/template/jobdashboard/jobfilterpanel.tpl", "serialize", "slimscroll", "uniform"
    ],
    function(CandidateManager, jobfilterTpl) {
        CandidateManager.module("CandidatesApp.JobFilterPanel.View", function (View, CandidateManager, Backbone, Marionette, $, _) {

            function searchMob(par) {
                var location = new Array();
                par.$el.find('#filter-scroll :checkbox:checked').each(function(a){location[a]=$(this).val()});
                /*$('.modal-backdrop').hide();
                $('.modaltest').modal('hide');*/
                par.trigger("filterJobs", 0, par.$el.find('.search_textbox').val(), location,par.$el.find('#experience').val());
                par.trigger("close");
            }
            View.JobFilterPanel = Marionette.ItemView.extend({
                template: jobfilterTpl,
                initailize: function() {
                    //$('#email-modal').modalmanager();
                },
                events: {
                    "click .close": "closemodal",
                    "keyup .location-search": "locationsearch",
                    "click .js-mobile-filter": "filtermobileJobs"
                },
                locationsearch: function(event) {
                        var valThis = this.$el.find('.location-search').val().toLowerCase();
                        if(valThis == ""){
                            $('#filter-scroll > .checkbox').show();
                        } else {
                            $('#filter-scroll > .checkbox').each(function(){
                                var text = $(this).text().toLowerCase();
                                (text.indexOf(valThis) >= 0) ? $(this).show() : $(this).hide();
                            });
                        };
                },
                filtermobileJobs: function(event) {
                    event.preventDefault();
                    searchMob(this);
                },
                filterSkills: function(event){

                },
                onShow: function() {
                    this.$el.find('#filter-scroll').slimScroll({
                        height: '131px',
                        alwaysVisible: true
                    });
                    var selectedCities = this.model.attributes.selectedCities;
                    for (var j = 0; j < selectedCities.length; j++) {
                        if(selectedCities[j] && selectedCities[j]!= '') {
                            var replaceSpaceLoc = selectedCities[j].replace(/ /g, '_');
                            var escapeSpecialChars = replaceSpaceLoc.replace(/([;&,\.\+\*\~':"\!\^#$%@\[\]\(\)=>\|])/g, '\\$1');
                            this.$el.find('#' + escapeSpecialChars).attr('checked', true);
                        }
                    }
                    if(this.model.attributes.selectedExp) {
                        this.$el.find('#experience').val(this.model.attributes.selectedExp)
                    }

                    this.$el.find('#filter-scroll input[type=checkbox]').uniform();
                },
                closemodal: function() {
                    this.trigger("close");
                }
            });
        });
        return CandidateManager.CandidatesApp.JobFilterPanel.View;
    });
